                       key=lambda v: v.get("created_at", 0))
        old_rules = pvers[-1].get("rules", []) if pvers else []
        return _out(event, {"policy_text": text, "procedure": (proc or {}).get("graph_json", {}),
                            "old_rules": old_rules,
                            "policy_version_id": event.get("policy_version_id", "POLICY-VX")})
    if op == "find_by_key":
